81	      int parallelism = Math.max(Math.min(markerPaths.size(), config.getRollbackParallelism()), 1);
82	      List<HoodieRollbackRequest> rollbackRequestList = context.map(markerPaths, markerFilePath -> {
83	        String typeStr = markerFilePath.substring(markerFilePath.lastIndexOf(".") + 1);
84	        IOType type = IOType.valueOf(typeStr);
85	        String filePathStr = WriteMarkers.stripMarkerSuffix(markerFilePath);
86	        StoragePath filePath = new StoragePath(basePath, filePathStr);
87	        String partitionPath = FSUtils.getRelativePartitionPath(new StoragePath(basePath), filePath.getParent());
88	        String fileId = FSUtils.getFileIdFromFilePath(filePath);
89	
90	        switch (type) {
91	          case MERGE:
92	          case CREATE:
93	            return createRollbackRequestForCreateAndMerge(fileId, partitionPath, filePath, instantToRollback);
94	          case APPEND:
95	            return createRollbackRequestForAppend(fileId, partitionPath, filePath, instantToRollback, filePathStr);
96	          default:
97	            throw new HoodieRollbackException("Unknown marker type, during rollback of " + instantToRollback);
98	        }
99	      }, parallelism);
100	      // The rollback requests for append only exist in table version 6 and below which require groupBy
101	      return table.version().greaterThanOrEquals(HoodieTableVersion.EIGHT)
102	          ? rollbackRequestList
103	          : RollbackUtils.groupRollbackRequestsBasedOnFileGroup(rollbackRequestList);
104	    } catch (Exception e) {
105	      throw new HoodieRollbackException("Error rolling back using marker files written for " + instantToRollback, e);
